import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import process from "node:process";
import { URL, fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { checkUrlLock, isAffectedUrlVersion, URL_ADVISORY } from "./check-url-advisory.mjs";

const lock = version => [
  "# This file is automatically generated.",
  "version = 4", "",
  "[[package]]", 'name = "eyezen"', 'version = "1.2.2"', "",
  "[[package]]", 'name = "url"', 'version = "' + version + '"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"', "",
].join("\n");

describe("url stack-overflow advisory lockfile guard", () => {
  it("accepts the exact patched 2.5.9 boundary and newer versions", () => {
    for (const version of ["2.5.9", "2.5.10", "2.6.0", "3.0.0"]) {
      expect(isAffectedUrlVersion(version), version).toBe(false);
      expect(checkUrlLock(lock(version)), version).toEqual([version]);
    }
  });

  it("rejects the vulnerable range and unverified first-fixed prereleases", () => {
    for (const version of ["1.0.0", "2.0.0", "2.5.0", "2.5.8", "2.5.9-rc.1"]) {
      expect(isAffectedUrlVersion(version), version).toBe(true);
      expect(() => checkUrlLock(lock(version))).toThrow(URL_ADVISORY);
    }
  });

  it("fails closed on malformed lockfiles and unknown url versions", () => {
    expect(() => checkUrlLock(null)).toThrow();
    expect(() => checkUrlLock("# no packages\nversion = 4")).toThrow();
    expect(() => checkUrlLock(lock("2.5"))).toThrow(/malformed/);
    expect(() => checkUrlLock(lock("v2.5.8"))).toThrow(/malformed/);
    expect(() => checkUrlLock(lock("99999999999999999999.5.9"))).toThrow(/oversized/);
    expect(() => checkUrlLock(lock("2.5.8").replace('version = "2.5.8"', ""))).toThrow(/no version/);
  });

  it("rejects any nested affected copy while allowing no url packages", () => {
    expect(checkUrlLock(lock("2.5.9").replace(/(?:\r?\n)?\[\[package\]\]\nname = "url"[\s\S]*/, ""))).toEqual([]);
    const mixed = lock("2.5.9") + '\n[[package]]\nname = "url"\nversion = "2.5.8"\n';
    expect(() => checkUrlLock(mixed)).toThrow(URL_ADVISORY);
  });

  it("exercises the exact CLI used by CI with exit-code behavior", () => {
    const script = fileURLToPath(new URL("./check-url-advisory.mjs", import.meta.url));
    const dir = mkdtempSync(path.join(tmpdir(), "eyezen-url-audit-"));
    try {
      const p = path.join(dir, "Cargo.lock");
      writeFileSync(p, lock("2.5.9"));
      const good = spawnSync(process.execPath, [script, p], { encoding: "utf8" });
      expect(good.status).toBe(0);
      expect(good.stdout).toContain(URL_ADVISORY);
      writeFileSync(p, lock("2.5.8"));
      const bad = spawnSync(process.execPath, [script, p], { encoding: "utf8" });
      expect(bad.status).toBe(1);
      expect(bad.stderr).toContain(URL_ADVISORY);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
